argv:
$ErrorActionPreference='Continue'
$o=[ordered]@{at=(Get-Date).ToUniversalTime().ToString('o')}
$o.daemonCount=@(Get-CimInstance Win32_Process -Filter "Name = 'tunnel-client.exe'" -ErrorAction SilentlyContinue).Count
try{$s=Invoke-RestMethod 'http://127.0.0.1:8080/api/status' -TimeoutSec 4
$e=[string]$s.tunnel_metadata_error
$o.metadataErrorPresent=($e.Length -gt 0)
$o.metadataHttpCode=if($e -match '(?<!\d)(400|401|403|404|409|424|429|500|502|503)(?!\d)'){$Matches[1]}else{'none'}
$o.regionBlocked=($e -match 'unsupported_country_region_territory')
$o.uptimeSeconds=$s.uptime_seconds
$o.routeCount=@($s.mcp_routes).Count
$o.tunnelIdMatches=($s.control_plane_tunnel_id -eq 'tunnel_6ac88c3d680c8191a475065208874b7c')
}catch{$o.statusError='operator_unavailable'}
try{$r=Invoke-WebRequest -Uri 'http://127.0.0.1:8080/readyz' -UseBasicParsing -TimeoutSec 3;$o.localReady=($r.StatusCode -eq 200)}catch{$o.localReady=$false}
try{$m=(Invoke-WebRequest 'http://127.0.0.1:8080/metrics' -UseBasicParsing -TimeoutSec 3).Content
$o.poll=@($m -split [char]10 | Where-Object {$_ -match '^(commands_poll_(cycles_total|errors_total|last_successful_timestamp_seconds))(\{[^}]*\})?\s+[-+0-9.eE]+'}|Select-Object -First 14 |ForEach-Object{[regex]::Replace($_,'\{[^}]*\}','{LABELS_REDACTED}')})
}catch{$o.metricsError='unavailable'}
$o|ConvertTo-Json -Depth 4 -Compress
